    {
      "slug": "teachers",
      "title": "Our Story & Team",
      "role": "editorial",
      "goal": "Build genuine emotional connection by telling the Sproutly origin story, introducing the people behind the brand, and communicating the values that drive every design decision \u2014 turning a clothing label into a brand parents feel proud to support.",
      "meta_description": "Meet the team behind Sproutly \u2014 the designers, parents, and makers who create kids' clothes built for real adventures.",
      "sections": [
        {
          "id": "teachers-section-1",
          "type": "page_header",
          "intent": "Set the editorial tone for a page that is about people and purpose, not product \u2014 signalling to the visitor that this is where the brand's heart lives.",
          "eyebrow": "Our Story",
          "headline": "We Started Sproutly Because Our Kids Kept Outgrowing Everything \u2014 Including Boring Clothes.",
          "subheadline": "A brand born on a rainy Tuesday, in a kitchen, by two parents who'd had enough.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "teachers-section-2",
          "type": "story_block",
          "intent": "Tell the founding story with warmth and specificity \u2014 a deliberate, unhurried narrative that makes the brand feel human, relatable, and rooted in real parenting experience.",
          "eyebrow": "How It Started",
          "headline": "From a Kitchen Table to 50,000 Families",
          "subheadline": null,
          "body": "In 2018, designers and parents Anya and Tom Beckett were standing in a changing room watching their daughter refuse to wear yet another scratchy, grey, shapeless outfit. They drove home, sketched their first design on the back of a school letter, and called it Sproutly. The idea was simple: make clothes that kids choose to wear, that survive a full season of actual childhood, and that parents don't feel guilty buying. Six years later, Sproutly dresses children in 14 countries \u2014 and Anya's daughter still has opinions about what she wears.",
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "teachers-section-2-asset-1",
              "kind": "illustration",
              "subject": "A warm, simple illustration of two adults sketching a children's outfit at a kitchen table, surrounded by fabric swatches, cups of tea, and a child's drawing on the fridge",
              "purpose": "Humanises the brand origin story and makes the founding moment feel personal and real",
              "quantity": 1,
              "used_by": [
                "teachers-section-2"
              ]
            }
          ]
        },
        {
          "id": "teachers-section-3",
          "type": "feature_grid",
          "intent": "Articulate the brand values as clear, memorable principles \u2014 giving parents a framework for understanding why Sproutly makes every decision it does.",
          "eyebrow": "What We Stand For",
          "headline": "Three Things We'll Never Compromise On",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Joy in Every Stitch",
              "description": "If a child wouldn't choose it themselves, we don't make it. Design starts with what kids love, then we make it parent-approved.",
              "metadata": {}
            },
            {
              "title": "Honest Materials",
              "description": "No greenwashing. Every fabric claim is certified, every supply chain is audited, and we publish our full supplier list online.",
              "metadata": {}
            },
            {
              "title": "Clothes That Last",
              "description": "We design for three seasons, not one. Durability is a feature, not a bonus \u2014 because landfill isn't an option.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "teachers-section-4",
          "type": "item_grid",
          "intent": "Introduce the core team with warmth and personality \u2014 putting real faces and voices behind the brand so parents feel they know who is making decisions about their children's clothes.",
          "eyebrow": "The Team",
          "headline": "Meet the People Behind the Label",
          "subheadline": "Designers, parents, makers, and a few very opinionated kids.",
          "body": null,
          "items": [
            {
              "title": "Anya Beckett \u2014 Co-Founder & Creative Director",
              "description": "Former textile designer turned full-time parent turned brand founder. Anya leads every collection with a single question: would my daughter actually wear this?",
              "metadata": {
                "based_in": "Bristol"
              }
            },
            {
              "title": "Tom Beckett \u2014 Co-Founder & Head of Product",
              "description": "Engineer by training, dad by calling. Tom obsesses over seam strength, wash tests, and the exact right weight of a hood drawstring.",
              "metadata": {
                "based_in": "Bristol"
              }
            },
            {
              "title": "Kezia Osei \u2014 Head of Design",
              "description": "Kezia brings 10 years of childrenswear experience and a colour instinct that has produced six of Sproutly's best-selling prints.",
              "metadata": {
                "based_in": "London"
              }
            },
            {
              "title": "Marcus Lim \u2014 Sustainability Lead",
              "description": "Marcus audits every supplier, certifies every fabric claim, and makes sure Sproutly's environmental commitments are real \u2014 not just marketing.",
              "metadata": {
                "based_in": "Manchester"
              }
            }
          ],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "teachers-section-4-asset-1",
              "kind": "illustration",
