@import "tailwindcss";

@theme {
  --color-cloud: #FFFFFF;
  --color-sky: #3AABF0;
  --color-sky-deep: #2A97D8;
  --color-mint: #4DDBB4;
  --color-mint-bright: #5DEBBF;
  --color-coral: #FF6B5B;
  --color-sun: #FFD93D;
  --color-purple: #B57BFF;
  --color-trail: #3D3535;
  --color-pebble: #F2F0ED;

  --font-heading: "Nunito", system-ui, sans-serif;
  --font-body: "DM Sans", system-ui, sans-serif;
  --font-accent: "Fredoka One", cursive;
}

@layer base {
  html {
    font-family: var(--font-body);
    color: var(--color-trail);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  body {
    background: var(--color-cloud);
  }
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    letter-spacing: -0.01em;
  }
}

/* Reveal helpers ---------------------------------------------------------- */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s cubic-bezier(.2,.7,.2,1), transform 0.7s cubic-bezier(.2,.7,.2,1);
  will-change: opacity, transform;
}
.reveal.in {
  opacity: 1;
  transform: translateY(0);
}
.reveal-scale {
  opacity: 0;
  transform: scale(.96);
  transition: opacity 0.7s ease-out, transform 0.7s cubic-bezier(.2,.7,.2,1);
}
.reveal-scale.in {
  opacity: 1;
  transform: scale(1);
}
.reveal-left {
  opacity: 0;
  transform: translateX(-40px);
  transition: opacity 0.7s ease-out, transform 0.7s cubic-bezier(.2,.7,.2,1);
}
.reveal-left.in {
  opacity: 1;
  transform: translateX(0);
}
.reveal-right {
  opacity: 0;
  transform: translateX(40px);
  transition: opacity 0.7s ease-out, transform 0.7s cubic-bezier(.2,.7,.2,1);
}
.reveal-right.in {
  opacity: 1;
  transform: translateX(0);
}

/* Hero word stagger */
@keyframes wordIn {
  0% { opacity: 0; transform: translateY(18px) scale(.84); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.word-stagger > span {
  display: inline-block;
  opacity: 0;
  animation: wordIn 0.55s cubic-bezier(.2,.8,.25,1) forwards;
}

@keyframes fadeUp {
  0% { opacity: 0; transform: translateY(14px); }
  100% { opacity: 1; transform: translateY(0); }
}
.anim-fade-up {
  animation: fadeUp 0.7s cubic-bezier(.2,.8,.25,1) both;
}

@keyframes dropIn {
  0% { opacity: 0; transform: translateY(-12px); }
  100% { opacity: 1; transform: translateY(0); }
}
.anim-drop-in {
  animation: dropIn 0.5s cubic-bezier(.2,.8,.25,1) both;
}

@keyframes scaleIn {
  0% { opacity: 0; transform: scale(.9); }
  60% { opacity: 1; transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}
.anim-scale-in {
  animation: scaleIn 0.6s cubic-bezier(.4,1.4,.5,1) both;
}

@keyframes floatY {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}
.anim-float {
  animation: floatY 4s ease-in-out infinite;
}
.anim-float-slow {
  animation: floatY 6s ease-in-out infinite;
}

@keyframes pulseDot {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.15); }
}
.anim-pulse-dot {
  animation: pulseDot 1.2s cubic-bezier(.4,0,.6,1) infinite;
}

@keyframes ctaPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.02); }
}
.anim-cta-pulse {
  animation: ctaPulse 3s ease-in-out infinite;
}

@keyframes drift {
  0% { background-position: 0 0; }
  100% { background-position: 200px 0; }
}
.anim-drift {
  animation: drift 60s linear infinite;
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(200%); }
}
.shimmer-sweep::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,0.18) 50%, transparent 70%);
  transform: translateX(-100%);
  animation: shimmer 4.5s ease-in-out infinite;
  pointer-events: none;
}

@keyframes blobFloat {
  0%, 100% { transform: translate(0,0) scale(1); }
  50% { transform: translate(4px,-8px) scale(1.04); }
}
.anim-blob {
  animation: blobFloat 6s ease-in-out infinite;
}
.anim-blob-2 {
  animation: blobFloat 7.5s ease-in-out infinite reverse;
}
.anim-blob-3 {
  animation: blobFloat 9s ease-in-out infinite;
}

@keyframes spinSlow {
  to { transform: rotate(360deg); }
}
.anim-spin-slow {
  animation: spinSlow 16s linear infinite;
}

@keyframes drawIn {
  0% { stroke-dashoffset: 1000; }
  100% { stroke-dashoffset: 0; }
}

.headline-bleed {
  font-family: var(--font-heading);
  font-weight: 900;
  letter-spacing: -0.02em;
  line-height: 1.02;
}

.eyebrow {
  font-family: var(--font-accent);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.accent-font {
  font-family: var(--font-accent);
}

/* Underline-grow link */
.link-underline {
  position: relative;
}
.link-underline::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 2px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.3s ease;
}
.link-underline:hover::after,
.link-underline:focus-visible::after {
  transform: scaleX(1);
}

/* Wavy bottom mask */
.wave-bottom {
  -webkit-mask-image: radial-gradient(ellipse 100% 36px at 50% 100%, transparent 70%, black 71%);
          mask-image: radial-gradient(ellipse 100% 36px at 50% 100%, transparent 70%, black 71%);
}

/* Accordion */
details > summary { list-style: none; cursor: pointer; }
details > summary::-webkit-details-marker { display: none; }
details[open] summary .chev { transform: rotate(180deg); }
.chev { transition: transform 0.25s ease; }

@keyframes openPop {
