  text-transform: uppercase;
}

.accent-font {
  font-family: var(--font-accent);
}

/* Underline-grow link */
.link-underline {
  position: relative;
}
.link-underline::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 2px;
  background: currentColor;
