import { createSignal, onMount, onCleanup } from 'solid-js';
import { Logo } from './Illustrations';

export default function Nav(props) {
  const [scrolled, setScrolled] = createSignal(false);
  const [open, setOpen] = createSignal(false);

  onMount(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    onCleanup(() => window.removeEventListener('scroll', onScroll));
  });

  const links = [
    { href: '/', label: 'Home', slug: 'home' },
    { href: '/classes.html', label: 'Collections', slug: 'classes' },
    { href: '/teachers.html', label: 'Our Story', slug: 'teachers' },
    { href: '/faq.html', label: 'FAQ', slug: 'faq' },
  ];

  // The hero (home, enroll) uses transparent over a blue background
  const onBlueHero = () => props.transparent && !scrolled();

  return (
    <header
      class="fixed top-0 left-0 right-0 z-50 transition-all duration-300"
      classList={{
        'bg-cloud/95 backdrop-blur-md shadow-[0_2px_18px_rgba(61,53,53,0.06)]': !onBlueHero(),
        'bg-transparent': onBlueHero(),
      }}
    >
      <div class="max-w-[1280px] mx-auto px-5 sm:px-8 h-16 sm:h-20 flex items-center justify-between">
        <a href="/" class="flex items-center gap-2 group">
          <Logo color={onBlueHero() ? '#FFFFFF' : '#3AABF0'} />
          <span
            class="font-accent text-xl tracking-wide"
            classList={{ 'text-cloud': onBlueHero(), 'text-trail': !onBlueHero() }}
          >
            Sproutly
          </span>
        </a>

        <nav class="hidden md:flex items-center gap-7">
          {links.map((l) => (
            <a
              href={l.href}
              class="link-underline text-[15px] font-medium tracking-wide transition-colors"
              classList={{
                'text-cloud/90 hover:text-cloud': onBlueHero(),
                'text-trail/80 hover:text-trail': !onBlueHero(),
                'text-sky': !onBlueHero() && l.slug === props.slug,
              }}
            >
              {l.label}
            </a>
          ))}
          <a
            href="/enroll.html"
            class="ml-2 inline-flex items-center gap-1 px-4 py-2 rounded-full font-medium text-[14px] transition-all duration-200 hover:scale-[1.03]"
            classList={{
              'bg-cloud text-sky shadow-sm hover:shadow-md': onBlueHero(),
              'bg-coral text-cloud hover:bg-coral/90 shadow-sm hover:shadow-md': !onBlueHero(),
            }}
          >
            Join Club
          </a>
        </nav>

        <button
          class="md:hidden p-2 rounded-lg"
          aria-label="Toggle menu"
          onClick={() => setOpen(!open())}
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path
              d="M4 6h16M4 12h16M4 18h16"
              stroke={onBlueHero() ? '#FFFFFF' : '#3D3535'}
              stroke-width="2"
              stroke-linecap="round"
            />
          </svg>
        </button>
      </div>

      {open() && (
        <div class="md:hidden bg-cloud border-t border-pebble">
          <div class="px-6 py-4 flex flex-col gap-3">
            {links.map((l) => (
              <a href={l.href} class="py-2 text-trail font-medium">
                {l.label}
              </a>
            ))}
            <a
              href="/enroll.html"
              class="mt-2 inline-block bg-coral text-cloud px-5 py-3 rounded-full text-center font-medium"
            >
              Join the Club
            </a>
          </div>
        </div>
      )}
    </header>
  );
}

