// Library of inline SVG illustrations used across the Sproutly site.
// All visuals are bespoke and built with the brand palette.

export function Logo(props) {
  const c = props.color || '#3AABF0';
  return (
    <svg width="32" height="32" viewBox="0 0 40 40" fill="none">
      <path
        d="M20 6c-2 4-1 6 1 9 3-3 6-3 9-2-1 5-5 8-10 8-1 3 0 6 0 9h-2c0-3 1-6 0-9-5 0-9-3-10-8 3-1 6-1 9 2 2-3 3-5 1-9 1-1 1-1 2 0z"
        fill={c}
      />
      <circle cx="20" cy="22" r="1.6" fill="#FFD93D" />
    </svg>
  );
}

// Hero illustration: a running child with trailing stars and leaves
export function RunningChild() {
  return (
    <svg viewBox="0 0 520 520" class="w-full h-auto" aria-hidden="true">
      <defs>
        <linearGradient id="hairG" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#3D3535" />
          <stop offset="1" stop-color="#5a4a4a" />
        </linearGradient>
      </defs>
      {/* trailing stars and leaves */}
      <g class="anim-spin-slow" style="transform-origin: 70px 140px;">
        <path d="M60 130 l8 4 l4 8 l4 -8 l8 -4 l-8 -4 l-4 -8 l-4 8 z" fill="#FFD93D" />
      </g>
      <g class="anim-spin-slow" style="transform-origin: 110px 200px; animation-duration:12s">
        <path d="M100 195 q5 -10 16 -8 q8 6 0 14 q-12 4 -16 -6 z" fill="#4DDBB4" />
      </g>
      <g class="anim-spin-slow" style="transform-origin: 60px 260px; animation-duration:14s">
        <path d="M55 255 l6 3 l3 6 l3 -6 l6 -3 l-6 -3 l-3 -6 l-3 6 z" fill="#B57BFF" />
      </g>
      <g class="anim-spin-slow" style="transform-origin: 130px 320px; animation-duration:10s">
        <path d="M122 315 q6 -10 18 -7 q6 7 -2 14 q-12 4 -16 -7 z" fill="#FFD93D" />
      </g>
      <g class="anim-spin-slow" style="transform-origin: 90px 380px; animation-duration:15s">
        <path d="M82 375 l7 4 l4 7 l4 -7 l7 -4 l-7 -4 l-4 -7 l-4 7 z" fill="#FF6B5B" />
      </g>

      {/* legs/shoes — back leg first */}
      <g>
        <path d="M250 360 q-20 50 -50 70 q-6 4 -10 -2 q-2 -6 4 -12 q22 -20 36 -54 z" fill="#3D3535" />
        <ellipse cx="195" cy="430" rx="22" ry="8" fill="#FF6B5B" />
        <ellipse cx="195" cy="427" rx="22" ry="6" fill="#FFFFFF" />
      </g>

      {/* shorts */}
      <path d="M220 300 q60 -25 130 -5 q-2 30 -10 60 q-30 8 -60 6 q-30 -2 -60 -8 q0 -28 0 -53 z" fill="#3AABF0" />
      <path d="M255 320 q35 -8 70 -2 q-2 18 -6 30 q-30 4 -60 -2 q-4 -14 -4 -26 z" fill="#2A97D8" />

      {/* front leg */}
      <g>
