// Sproutly Club membership badge illustration
export function ClubBadge() {
  return (
    <svg viewBox="0 0 360 380" class="w-full h-auto drop-shadow-2xl" aria-hidden="true">
      <defs>
        <linearGradient id="badgeG" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#FFFFFF" />
          <stop offset="1" stop-color="#FFF7DC" />
        </linearGradient>
      </defs>
      {/* ribbon back */}
      <path d="M70 320 l30 50 l20 -30 l40 30 l-30 -70 z" fill="#FF6B5B" />
      <path d="M290 320 l-30 50 l-20 -30 l-40 30 l30 -70 z" fill="#FF6B5B" />
      <path d="M70 320 l30 50 l-10 -42 z" fill="#d65647" />
      <path d="M290 320 l-30 50 l10 -42 z" fill="#d65647" />

      {/* scallop */}
      <g>
        {Array.from({ length: 16 }).map((_, i) => {
          const a = (i / 16) * Math.PI * 2;
          const cx = 180 + Math.cos(a) * 138;
          const cy = 180 + Math.sin(a) * 138;
          return <circle cx={cx} cy={cy} r="20" fill="#FFD93D" />;
        })}
