  if (t === 'pj') {
    return (
      <svg viewBox="0 0 320 380" class="w-full h-full block">
        <rect width="320" height="380" fill="#1f2440" />
        {Array.from({ length: 20 }).map((_, i) => {
          const x = (i * 73) % 320;
          const y = (i * 41) % 380;
          return <circle cx={x} cy={y} r="2" fill="#FFD93D" opacity={0.6 + (i % 3) * 0.15} />;
