        <rect width="320" height="380" fill={bg} />
        <g transform="translate(160 190)">
          <path d="M-50 -80 L-20 -100 Q0 -80 20 -100 L50 -80 L84 -50 L70 -30 L60 -42 L60 100 L-60 100 L-60 -42 L-70 -30 L-84 -50 Z" fill="#FFFFFF" stroke="#3D3535" stroke-width="2" />
