          <rect x="-60" y="60" width="120" height="14" fill="#B57BFF" />
        </g>
      </svg>
    );
  }
  if (t === 'welly') {
    return (
      <svg viewBox="0 0 320 380" class="w-full h-full block">
        <rect width="320" height="380" fill={bg} />
