import { onMount, onCleanup, createSignal } from 'solid-js';

/**
 * Reveal — wraps content in a div that fades / slides in when it enters the viewport.
 * Props: as ("div" default), variant ("up" | "scale" | "left" | "right"), delay (ms), threshold, class, ...rest
 */
export default function Reveal(props) {
  let el;
  const variant = props.variant || 'up';
  const variantClass = {
    up: 'reveal',
    scale: 'reveal-scale',
    left: 'reveal-left',
    right: 'reveal-right',
  }[variant];
  const delay = props.delay || 0;

  onMount(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setTimeout(() => el?.classList.add('in'), delay);
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: props.threshold ?? 0.12, rootMargin: '0px 0px -40px 0px' },
    );
    observer.observe(el);
    onCleanup(() => observer.disconnect());
  });

  return (
    <div
      ref={el}
      class={`${variantClass} ${props.class || ''}`}
      style={props.style}
    >
      {props.children}
    </div>
  );
}

/** CountUp — animates a number from 0 to target when in view. */
export function CountUp(props) {
  const [val, setVal] = createSignal(0);
  let el;
  const duration = props.duration || 1400;
  onMount(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const start = performance.now();
            const tick = (now) => {
              const t = Math.min(1, (now - start) / duration);
              const eased = 1 - Math.pow(1 - t, 3);
              setVal(eased * props.to);
              if (t < 1) requestAnimationFrame(tick);
            };
            requestAnimationFrame(tick);
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.3 },
    );
    observer.observe(el);
    onCleanup(() => observer.disconnect());
  });
  return (
    <span ref={el} class={props.class}>
      {props.format ? props.format(val()) : Math.round(val())}
    </span>
  );
}

/** WordStagger — splits text into spans that animate in left-to-right. */
export function WordStagger(props) {
  const words = (props.text || '').split(' ');
  return (
    <span class={`word-stagger ${props.class || ''}`}>
      {words.map((w, i) => (
        <>
          <span
            style={{
              'animation-delay': `${(props.baseDelay || 100) + i * (props.step || 90)}ms`,
            }}
          >
            {w}
          </span>
          {i < words.length - 1 ? ' ' : ''}
        </>
      ))}
    </span>
  );
}

